    protect();structure=OUT/'structural_v2/RESULT.json';direct=OUT/'gta_free_native_v1/RESULT.json';ss=json.loads(structure.read_text());dd=json.loads(direct.read_text());assert ss['status']==dd['status']=='PASS'
