    d=json.loads((REPORTS/'DENSE_DATASET_MANIFEST.json').read_text());assert d['status']=='PASS';selected=sorted({tuple(r['record_key']) for r in d['tiny_frozen_selection'].values()})
    files=list((ROOT/'gtr/modeling/jev_stage2').glob('*.py'))+[ROOT/'reproduction_tools'/n for n in ['jev_phase13_common.py','jev_phase13_learning.py','train_jev_stage2.py','jev_phase13_runtime.py','build_dense_jev_stage2_dataset.py']]+[ROOT/'gtr/modeling/meta_arch/gtr_rcnn.py']
    protocol={'status':'FROZEN_BEFORE_TRAINING','binding':binding(),'models':VARIANTS,'seeds':SEEDS,'dataset_version':'dense_native_v3','dataset_SHA256':{str(r['video']):r['DATASET']['SHA256'] for r in d['videos']},'updates':{'tiny':1000,'pilot':1000,'formal':20000},'batch_payloads':4,'learning_rate':.0001,'weight_decay':.01,'gradient_clip':1.,'optimizer':'AdamW FP32; constant LR; no H32/reward/future values','loss':'multi-positive certified-option CE +0.25 loss-augmented lawful joint-assignment margin +0.1 certified-option Brier','sampling':'all natural real MATCH payloads uniformly shuffled without replacement per epoch, supervised rows only; no corrective balancing/no GT input','assessment_interval':{'tiny':100,'pilot':250,'formal':2000},'assessment_train_groups':64,'assessment_record_keys':d['assessment_record_keys'],'tiny_record_keys':[list(k) for k in selected],'tiny_selection_categories':d['tiny_frozen_selection'],'tiny_gate':{'MATCH_certified_accuracy_min':.95,'REACT_scope':'only frozen real examples, engineering learnability; not enough formal support','unknowns':'never forced into negative labels'},'pilot_gate':{'finite_losses_gradients':True,'normal_matching_certified_accuracy_min':.85,'architecture_changes_after_pilot':'new version and repeated gates required; none silently permitted'},'formal_primary_checkpoint':'LAST at common 20000 updates; BEST kept as diagnostic only','temperature_grid':[.25,.5,1.,2.,4.],'temperature_scope':'development fixed candidate audit groups, certified options only; T positive per task does not change raw-logit Hungarian assignment','REACT_qualification':d['REACT_qualification'],'MEMORY_qualification':d['MEMORY_qualification'],'training_source_SHA256':{str(p.relative_to(ROOT)):sha(p) for p in files},'scientific_gates':{'G5':'Full 3-seed mean strict pooled HOTA > B1 and AssA > B1; IDSW <=1.25xB1; severe-collapse if HOTA drops >5 points or IDSW doubles','G6':'3 seeds, equal 20000 updates, all style baselines complete; registered capacity ratio Full/largest ordinary >=0.9 and <=1.1','G7':'exploratory independent-value GO only if Full mean HOTA and AssA exceed strongest style by >=0.5 points, no seed has negative pooled HOTA delta, and >=2 structural ablations reduce mean HOTA; not a significance/population-generalization claim with 3 preexposed scenes','G8':'warm Stage2 p95 <=10ms per camera payload and full online end-to-end >=25 two-camera scene FPS on one V100; actual image I/O included; no added-stage latency sum pretending full FPS','G9':'NO_GO: inherited Stage1 already pretrained on all TRAIN24, including heldout; keep20/21/22 sealed regardless development scores'},'onpolicy_preregistered':{'rounds_max':1,'training_only':TRAIN,'eligibility':'Full formal TRAIN fixed-audit certified accuracy >=0.90 and clean-positive normal association present; no hard GT label for contaminated native histories','updates_per_model':4000,'same_baseline_budget':True,'blend':'50% original dense groups and 50% each model own-state TRAIN groups; a separate 24000-update total comparison, never compared as common20000','learning_rate':.00005,'REACT':'remains frozen fallback unless separate real support audit reaches frozen100 positives across3 TRAIN videos; no automatic lifecycle claim'},'heldout':'SEALED','Full24':False,'official_TEST':False}
